-- One-off restore of every lineup from the user's own backup, after
-- the shared-sync merge bug (fixed in lib/star/lineupStore.ts) wiped the
-- table's first real contents on the very next sync following the
-- star_lineups.sql migration. Every value below is taken verbatim from that
-- backup — club-name duplicates, generated placeholder ids ("gen:Club:N"),
-- empty managers, stray whitespace and all — so this restores things to
-- exactly the state they were in, not a cleaned-up version of it.
--
-- Idempotent: ON CONFLICT (club) DO UPDATE, so running it twice is safe and
-- just re-writes the same 129 rows.

ON CONFLICT (club) DO UPDATE SET
  formation  = excluded.formation,
  xi         = excluded.xi,
  bench      = excluded.bench,
  manager    = excluded.manager,
  updated_at = excluded.updated_at;

